#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>
#include <climits>
#include <iomanip>
#include <numeric>
#include <functional>
using namespace std;

using i64 = long long;
const i64 MOD = 1000000007LL;
const i64 MOD1 = 998244353LL;
constexpr int T = 14;

i64 mod_pow(i64 b, i64 e, i64 m) {
    i64 r = 1;
    b %= m;
    while (e) {
        if (e & 1) r = (r * b) % m;
        b = (b * b) % m;
        e >>= 1;
    }
    return r;
}

namespace linear_alg {
    using vi = vector<i64>;

    vi BM(const vi& s) {
        int n = s.size();
        vi cur, ls;
        int lf = -1;
        i64 ld = 0;
        for (int i = 0; i < n; ++i) {
            i64 val = 0;
            for (int j = 0; j < (int)cur.size(); ++j)
                val = (val + s[i - j - 1] * cur[j]) % MOD;
            val = (val - s[i]) % MOD;
            if (val == 0) continue;
            if (cur.empty()) {
                cur.assign(i + 1, 0);
                lf = i;
                ld = val;
                continue;
            }
            i64 k = (-val * mod_pow(ld, MOD - 2, MOD)) % MOD;
            vi c(i - lf - 1, 0);
            c.push_back(k);
            for (size_t j = 0; j < ls.size(); ++j)
                c.push_back((-ls[j] * k) % MOD);
            if ((int)c.size() < (int)cur.size()) c.resize(cur.size());
            for (size_t j = 0; j < cur.size(); ++j)
                c[j] = (c[j] + cur[j]) % MOD;
            if ((int)cur.size() < i - lf + (int)ls.size()) {
                ls = cur;
                lf = i;
                ld = val;
            }
            cur = c;
        }
        for (auto& x : cur) x = (x % MOD + MOD) % MOD;
        return cur;
    }

    vi h, a;
    int m;

    void mul(vi& p, const vi& q) {
        vi t(m * 2, 0);
        for (int i = 0; i < m; ++i) if (p[i])
            for (int j = 0; j < m; ++j)
                t[i + j] = (t[i + j] + p[i] * q[j]) % MOD;
        for (int i = m * 2 - 1; i >= m; --i) if (t[i])
            for (int j = m - 1; j >= 0; --j)
                t[i - j - 1] = (t[i - j - 1] + t[i] * h[j]) % MOD;
        for (int i = 0; i < m; ++i) p[i] = t[i];
    }

    i64 calc(i64 k) {
        vi s(m, 0), t(m, 0);
        s[0] = 1;
        if (m != 1) t[1] = 1;
        else t[0] = h[0];
        while (k) {
            if (k & 1) mul(s, t);
            mul(t, t);
            k >>= 1;
        }
        i64 res = 0;
        for (int i = 0; i < m; ++i)
            res = (res + s[i] * a[i]) % MOD;
        return (res % MOD + MOD) % MOD;
    }

    i64 solve(const vi& seq, i64 n) {
        if (n < (i64)seq.size()) return seq[n];
        h = BM(seq);
        m = h.size();
        if (m == 0) return 0;
        a = vi(h.begin(), h.end());
        for (int i = 0; i < m; ++i) a[i] = seq[i];
        return calc(n);
    }
}

i64 f(i64 x, i64 up) {
    i64 cnt = 0;
    string s = to_string(x);
    int len = s.length();
    if (x > 0) cnt++;
    for (int i = 1; i < T; i++) {
        i64 lo = 1, hi = x;
        for (int j = 0; j + 1 < i; j++) lo *= 10;
        for (int j = len; j < i; j++) hi *= 10;
        if (i < len) {
            string pre = s.substr(0, i);
            hi = stoll(pre) + 1;
        }
        if (hi > up) hi = up;
        if (hi > lo) cnt += hi - lo;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 n;
    cin >> n;
    n++;
    i64 limit = n;

    i64 adj = (n % MOD) * ((n / MOD1) + 2) % MOD;
    adj = (MOD - adj) % MOD;

    i64 res = 0;
    for (i64 off = -n / MOD1 - 1; off <= n / MOD1 + 1; off++) {
        i64 cnt = 0;
        for (int d = 0; d < T; d++) {
            i64 L = 0, R = 1;
            if (d >= 1) {
                L = 1;
                for (int k = 0; k + 1 < d; k++) L *= 10;
                R = L * 10;
            }
            if (R > n) R = n;
            i64 lastR = R;
            if (L < R) {
                L--;
                while (R - L > 1) {
                    i64 mid = (L + R) >> 1;
                    if (f(mid, limit) > mid + MOD1 * off - 1) R = mid;
                    else L = mid;
                }
                cnt += lastR - R;
            }
        }
        res += cnt;
    }

    res %= MOD;
    res = ((-res - adj) % MOD * MOD1) % MOD;
    res = (res % MOD + MOD) % MOD;
    cout << res << '\n';

    return 0;
}
